/**
 * Breakpoint Constants and Utilities
 *
 * These breakpoint values align with DSAi design tokens and match Bootstrap 5 defaults.
 * Use these constants to ensure consistency between CSS media queries and JavaScript logic.
 */

/**
 * DSAi breakpoint constants aligned with design tokens.
 * These match the SCSS breakpoint variables generated by @dsai-io/tools.
 */
export const BREAKPOINTS = {
  /** Extra small: 0px and up */
  xs: 0,
  /** Small: 576px and up */
  sm: 576,
  /** Medium: 768px and up (tablets) */
  md: 768,
  /** Large: 992px and up (desktops) */
  lg: 992,
  /** Extra large: 1200px and up (large desktops) */
  xl: 1200,
  /** Extra extra large: 1400px and up (wide screens) */
  xxl: 1400,
} as const;

export type Breakpoint = keyof typeof BREAKPOINTS;

/**
 * Generate a min-width media query for a breakpoint.
 *
 * @example
 * ```ts
 * breakpointUp('md') // "(min-width: 768px)"
 * ```
 *
 * @param breakpoint - The breakpoint key (xs, sm, md, lg, xl, xxl)
 * @returns CSS media query string for min-width
 */
export function breakpointUp(breakpoint: Breakpoint): string {
  return `(min-width: ${BREAKPOINTS[breakpoint]}px)`;
}

/**
 * Generate a max-width media query for a breakpoint.
 * Uses breakpoint - 0.02px to avoid overlap with min-width queries.
 *
 * @example
 * ```ts
 * breakpointDown('md') // "(max-width: 767.98px)"
 * ```
 *
 * @param breakpoint - The breakpoint key (xs, sm, md, lg, xl, xxl)
 * @returns CSS media query string for max-width
 */
export function breakpointDown(breakpoint: Breakpoint): string {
  const value = BREAKPOINTS[breakpoint] - 0.02;
  return `(max-width: ${value}px)`;
}

/**
 * Generate a media query for a range between two breakpoints.
 *
 * @example
 * ```ts
 * breakpointBetween('sm', 'lg') // "(min-width: 576px) and (max-width: 991.98px)"
 * ```
 *
 * @param min - The minimum breakpoint (inclusive)
 * @param max - The maximum breakpoint (exclusive)
 * @returns CSS media query string for the range
 */
export function breakpointBetween(min: Breakpoint, max: Breakpoint): string {
  return `${breakpointUp(min)} and ${breakpointDown(max)}`;
}

/**
 * Get the pixel value for a breakpoint.
 *
 * @param breakpoint - The breakpoint key
 * @returns The pixel value as a number
 */
export function getBreakpointValue(breakpoint: Breakpoint): number {
  return BREAKPOINTS[breakpoint];
}

/**
 * useMediaQuery Hook
 *
 * React hooks for responsive design and media query tracking.
 * Provides reactive updates when viewport or media features change.
 */

export { useMediaQuery } from './useMediaQuery';
export type { UseMediaQueryOptions } from './useMediaQuery';

export { useIsDesktop, useIsLargeDesktop, useIsMobile, useIsTablet } from './useMediaQuery.helpers';

export {
  BREAKPOINTS,
  breakpointBetween,
  breakpointDown,
  breakpointUp,
  getBreakpointValue,
} from './breakpoints';
export type { Breakpoint } from './breakpoints';

/**
 * Convenience hooks for common breakpoint checks.
 *
 * These hooks provide named shortcuts for frequently-used media queries,
 * making component code more readable and maintainable.
 */

import { breakpointDown, breakpointUp } from './breakpoints';
import { useMediaQuery } from './useMediaQuery';

import type { UseMediaQueryOptions } from './useMediaQuery';

/**
 * Returns `true` if viewport is mobile (< 768px).
 *
 * This matches screens smaller than the "md" breakpoint,
 * typically phones in portrait and landscape modes.
 *
 * @example
 * ```tsx
 * function Header() {
 *   const isMobile = useIsMobile();
 *
 *   return (
 *     <header>
 *       {isMobile ? <MobileNav /> : <DesktopNav />}
 *     </header>
 *   );
 * }
 * ```
 *
 * @param options - Configuration options for SSR behavior
 * @returns `true` if viewport width is less than 768px
 */
export function useIsMobile(options?: UseMediaQueryOptions): boolean {
  return useMediaQuery(breakpointDown('md'), options);
}

/**
 * Returns `true` if viewport is tablet or larger (>= 768px).
 *
 * This matches screens at or above the "md" breakpoint,
 * including tablets and desktops.
 *
 * @example
 * ```tsx
 * function Sidebar() {
 *   const isTablet = useIsTablet();
 *
 *   if (!isTablet) return null;
 *
 *   return <aside>Tablet/Desktop sidebar</aside>;
 * }
 * ```
 *
 * @param options - Configuration options for SSR behavior
 * @returns `true` if viewport width is 768px or greater
 */
export function useIsTablet(options?: UseMediaQueryOptions): boolean {
  return useMediaQuery(breakpointUp('md'), options);
}

/**
 * Returns `true` if viewport is desktop or larger (>= 992px).
 *
 * This matches screens at or above the "lg" breakpoint,
 * typically desktop monitors and large tablets in landscape.
 *
 * @example
 * ```tsx
 * function ProductGrid() {
 *   const isDesktop = useIsDesktop();
 *   const columns = isDesktop ? 4 : 2;
 *
 *   return <Grid columns={columns} />;
 * }
 * ```
 *
 * @param options - Configuration options for SSR behavior
 * @returns `true` if viewport width is 992px or greater
 */
export function useIsDesktop(options?: UseMediaQueryOptions): boolean {
  return useMediaQuery(breakpointUp('lg'), options);
}

/**
 * Returns `true` if viewport is large desktop or larger (>= 1200px).
 *
 * This matches screens at or above the "xl" breakpoint,
 * typically large desktop monitors and wide screens.
 *
 * @example
 * ```tsx
 * function Dashboard() {
 *   const isLargeDesktop = useIsLargeDesktop();
 *
 *   return (
 *     <div>
 *       {isLargeDesktop && <DetailedAnalytics />}
 *       <MainContent />
 *     </div>
 *   );
 * }
 * ```
 *
 * @param options - Configuration options for SSR behavior
 * @returns `true` if viewport width is 1200px or greater
 */
export function useIsLargeDesktop(options?: UseMediaQueryOptions): boolean {
  return useMediaQuery(breakpointUp('xl'), options);
}

/**
 * useMediaQuery Hook
 *
 * Tracks whether a CSS media query matches the current viewport/environment.
 * Provides reactive updates when media query state changes.
 */

import { useSyncExternalStore } from 'react';

import { isBrowser } from '../../utils';

export interface UseMediaQueryOptions {
  /**
   * Default value to return during SSR or when browser APIs are unavailable.
   * @default false
   */
  defaultValue?: boolean;
}

/**
 * Tracks whether a CSS media query matches the current viewport.
 *
 * This hook listens to the window.matchMedia API and updates reactively when
 * the media query match status changes. It's SSR-safe and handles hydration properly.
 *
 * Features:
 * - Accepts any valid CSS media query string
 * - Updates reactively when viewport changes
 * - SSR-safe with configurable default values
 * - Handles hydration mismatch gracefully
 * - Proper cleanup of event listeners
 *
 * @example
 * ```tsx
 * // Basic usage
 * function ResponsiveComponent() {
 *   const isMobile = useMediaQuery('(max-width: 767.98px)');
 *
 *   return (
 *     <div>
 *       {isMobile ? <MobileLayout /> : <DesktopLayout />}
 *     </div>
 *   );
 * }
 * ```
 *
 * @example
 * ```tsx
 * // With custom SSR default
 * function Header() {
 *   const prefersLight = useMediaQuery(
 *     '(prefers-color-scheme: light)',
 *     { defaultValue: true }
 *   );
 *
 *   return <header className={prefersLight ? 'light' : 'dark'} />;
 * }
 * ```
 *
 * @example
 * ```tsx
 * // Using breakpoint helpers
 * import { breakpointUp } from './breakpoints';
 *
 * function Grid() {
 *   const isDesktop = useMediaQuery(breakpointUp('lg'));
 *   const columns = isDesktop ? 3 : 1;
 *
 *   return <div style={{ gridTemplateColumns: `repeat(${columns}, 1fr)` }} />;
 * }
 * ```
 *
 * @param query - CSS media query string (e.g., "(max-width: 768px)")
 * @param options - Configuration options for SSR behavior
 * @returns `true` if the media query matches, `false` otherwise
 */
export function useMediaQuery(query: string, options: UseMediaQueryOptions = {}): boolean {
  const { defaultValue = false } = options;
  const canUseMatchMedia = (): boolean => {
    return isBrowser() && typeof window.matchMedia === 'function';
  };
  const supportsMatchMedia = canUseMatchMedia();

  const subscribe = (callback: () => void): (() => void) => {
    if (!supportsMatchMedia) {
      return () => {};
    }

    const mediaQueryList = window.matchMedia(query);

    // Modern browsers use addEventListener
    mediaQueryList.addEventListener('change', callback);

    return () => {
      mediaQueryList.removeEventListener('change', callback);
    };
  };

  const getSnapshot = (): boolean => {
    if (!supportsMatchMedia) {
      return defaultValue;
    }
    return window.matchMedia(query).matches;
  };

  const getServerSnapshot = (): boolean => {
    return defaultValue;
  };

  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}
